parameters.jsCode:
// Map the Slack modal submission onto the canonical request shape.
// No interpretation happens here: fields are copied, trimmed and typed only.
const state = $input.first().json.view?.state?.values ?? {};
const pick = (block, action) => state[block]?.[action]?.value
  ?? state[block]?.[action]?.selected_option?.value
  ?? null;

const trim = (v) => (typeof v === 'string' ? v.trim() : v);

return [{
  json: {
    submittedAt: new Date().toISOString(),
    requesterSlackId: $input.first().json.user?.id ?? null,
    typeCode: trim(pick('block_type', 'action_type')),
    title: trim(pick('block_title', 'action_title')),
    // Free text. Carried as data. Never concatenated into agent instructions.
    body: trim(pick('block_body', 'action_body')),
    businessJustification: trim(pick('block_justification', 'action_justification')),
    requestedBy: trim(pick('block_team', 'action_team')),
    targetDate: trim(pick('block_target_date', 'action_target_date')),
  }
}];

// Collect every missing field rather than failing on the first one, so the
// requester gets one complete list instead of a sequence of rejections.
const REQUIRED = ['typeCode', 'title', 'body', 'businessJustification', 'requestedBy'];
const VALID_TYPES = ['FEE', 'RAIL', 'RISK', 'RPT', 'MEX', 'INT'];

const item = $input.first().json;
const missingFields = REQUIRED.filter((f) => !item[f] || String(item[f]).length === 0);

if (item.typeCode && !VALID_TYPES.includes(item.typeCode)) {
  missingFields.push('typeCode (value not in ' + VALID_TYPES.join(', ') + ')');
}
if (item.body && String(item.body).length < 40) {
  missingFields.push('body (too short to draft from, minimum 40 characters)');
}

return [{ json: { ...item, missingFields, isValid: missingFields.length === 0 } }];

// Single source of routing truth inside the workflow.
// Mirrored in pipeline/routing-matrix.md. If the two disagree, the matrix is
// the document under review and this table is what actually runs, so a
// mismatch is a defect in both.
const ROUTING = {
  FEE:  { label: 'Fee schedule change',                template: 'brd-fee-change',         reviewerRole: 'Finance Approver',    reviewerChannel: 'C00000000001', parentPageId: '0000000001', publicationMode: 'standard',   reviewSlaHours: 48,  secondaryReview: [] },
  RAIL: { label: 'Payout rail or corridor enablement', template: 'brd-rail-enablement',    reviewerRole: 'Compliance Reviewer', reviewerChannel: 'C00000000002', parentPageId: '0000000002', publicationMode: 'standard',   reviewSlaHours: 120, secondaryReview: ['Backend Reviewer'] },
  RISK: { label: 'Fraud rule threshold adjustment',    template: 'brd-risk-threshold',     reviewerRole: 'Compliance Reviewer', reviewerChannel: 'C00000000002', parentPageId: '0000000003', publicationMode: 'draft-only', reviewSlaHours: 24,  secondaryReview: [] },
  RPT:  { label: 'Reconciliation or reporting request',template: 'brd-reporting',          reviewerRole: 'Finance Approver',    reviewerChannel: 'C00000000001', parentPageId: '0000000004', publicationMode: 'standard',   reviewSlaHours: 72,  secondaryReview: [] },
  MEX:  { label: 'Merchant onboarding exception',      template: 'brd-merchant-exception', reviewerRole: 'Compliance Reviewer', reviewerChannel: 'C00000000002', parentPageId: '0000000005', publicationMode: 'standard',   reviewSlaHours: 48,  secondaryReview: [] },
  INT:  { label: 'Merchant integration or API change', template: 'brd-integration',        reviewerRole: 'Backend Reviewer',    reviewerChannel: 'C00000000003', parentPageId: '0000000006', publicationMode: 'standard',   reviewSlaHours: 72,  secondaryReview: [] },
};

const item = $input.first().json;
const routing = ROUTING[item.typeCode];

// No default branch. An unknown type must not silently take the cheapest path.
if (!routing) {
  throw new Error('No routing rule for type code: ' + item.typeCode);
}

return [{ json: { ...item, routing } }];

